const raw = $input.first().json.stdout || '';
let plan;
try { plan = JSON.parse(raw.trim().split('\n').pop()); }
catch (e) { throw new Error('Could not parse the planner output. Raw:\n' + raw.slice(0, 600)); }
if (!plan.wouldBuild) throw new Error('Nothing to build — check RBL_DATA_ROOT points at the book folders.');
return [{ json: plan }];

const raw = $input.first().json.stdout || '';
let r;
try { r = JSON.parse(raw.trim().split('\n').pop()); }
catch (e) { throw new Error('Build produced no JSON summary. Raw tail:\n' + raw.slice(-800)); }

/* A PDF with zero call attempts is the signature of the call-log-as-lookup bug:
   accounts, outstanding and recovered all still look right, so it cannot be caught
   by eye. Treat it as a failure, never as a pass. */
const problems = [];
if (r.failedCount) problems.push(`${r.failedCount} book(s) failed`);
if ((r.zeroCallWarning || []).length) problems.push(`zero AI calls: ${r.zeroCallWarning.join(', ')}`);

return [{ json: { ...r, problems, healthy: problems.length === 0 } }];

